<section class="section"><h1>Lo que dicen nuestros clientes</h1><?php foreach ($testimonials as $testimonial): ?><article class="card"><h2><?php echo htmlspecialchars($testimonial->name, ENT_QUOTES, 'UTF-8'); ?></h2><p><?php echo htmlspecialchars($testimonial->message, ENT_QUOTES, 'UTF-8'); ?></p><p><?php echo str_repeat('★', $testimonial->rating); ?></p></article><?php endforeach; ?></section>
<section class="section"><h2>Déjanos tu opinión</h2><?php if ($success): ?><p class="alert alert--success"><?php echo htmlspecialchars($success, ENT_QUOTES, 'UTF-8'); ?></p><?php elseif ($error): ?><p class="alert alert--error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></p><?php endif; ?><form method="post"><input name="name" required><textarea name="message" required></textarea><select name="rating"><option value="5">5</option><option value="4">4</option><option value="3">3</option><option value="2">2</option><option value="1">1</option></select><?php echo $csrf; ?><button type="submit">Enviar</button></form></section>
